import sys
import time
import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection


class SshExecutor(ManagedObject):

    def __init__(self, host, user, password, port=22, **kwargs):
        super(SshExecutor, self).__init__(**kwargs)
        self._managed_ssh_connection = ManagedSshConnection(host=host, user=user, password=password, port=int(port))
        self.add_prerequisite(self._managed_ssh_connection)

    def execute(self, command, timeout=0.1):
        output = self._execute(command)
        output = output.split("daemon started successfully *")[-1].strip()
        time.sleep(timeout)
        logging.debug("output:{}".format(output))
        return output

    def _execute(self, command):
        tmp_file = "tmp.txt"
        command = "{} > {}".format(command, tmp_file)
        output = self._managed_ssh_connection.ssh_connection.execute(command)
        logging.debug("command {} : {}".format(command, output.strip()))
        self._download_file(
            remote_path=tmp_file, local_path=tmp_file, connection=self._managed_ssh_connection.ssh_connection)
        return self._read_log_file(tmp_file)

    def _download_file(self, remote_path, local_path, connection):
        logging.info("downloading file: from {} to {}".format(remote_path, local_path))
        fp = connection.files
        fp.get(remote_path, local_path)

    def _read_log_file(self, file_name):
        if sys.version.startswith("2"):
            with open(file_name) as fh:
                return fh.read()
        else:
            with open(file_name, "rb") as fh:
                return fh.read().decode()
